                 "The use of AI in healthcare is still in its early stages, but the potential for improving patient outcomes and reducing costs is enormous. \n";
map<string, int> keywordFrequency;
vector<string> words;
regex re("\\b\\w+\\b");
transform(sregex_iterator(article.begin(), article.end(), re),
          sregex_iterator(),
          back_inserter(words),
          [](auto match) { return match.str(); });
for (auto word : words)
{
    transform(word.begin(), word.end(), word.begin(), ::tolower);
