const styles = [
  {
    "name": "Seashell Bikini",
    "description": "This bikini is made from recycled materials and features a seashell-inspired design.",
    "colors": ["blue", "green", "purple"],
    "sizes": ["small", "medium", "large"],
    "price": 100
  },
  {
    "name": "Wave Swimsuit",
