    int max_count = 0;
    for (auto student : sources) {
        int count = 0;
        for (auto source : student.second) {
            count += sources_count[source];
        }
        if (count > max_count) {
            max_count = count;
            plagiarizer = student.first;
        }
    }
    cout << "The likely plagiarizer is student " << plagiarizer << "." << endl;
    return 0;
} 
The code uses a map to store the list of sources provided by each student, and another map to count the frequency of each source. It then iterates through each student's list of sources and counts the total frequency of all sources in their list. The student with the highest total frequency is considered the likely plagiarizer.

