```scala
// Define the Event model
case class Event(id: Long, name: String, date: LocalDate, time: LocalTime, location: String, description: String)
// Define the EventForm case class that maps to the form data
case class EventForm(name: String, date: LocalDate, time: LocalTime, location: String, description: String)
// Define the event form and event list routes
class SocialCommitteeController @Inject()(cc: ControllerComponents)(implicit ec: ExecutionContext) extends AbstractController(cc) {

  // Define the event form route
  def eventForm = Action { implicit request: Request[AnyContent] =>
    Ok(views.html.eventForm(eventForm))
  }

  // Define the event list route
  def eventList = Action.async { implicit request: Request[AnyContent] =>
    val events = EventDAO.getAllEvents()
    events.map { eventList =>
      Ok(views.html.eventList(eventList))
    }
  }

  // Define the event submission route
  def submitEventForm = Action.async { implicit request =>
    eventForm.bindFromRequest.fold(
      formWithErrors => Future.successful(BadRequest(views.html.eventForm(formWithErrors))),
      eventData => {
        val newEvent = EventDAO.createEvent(eventData.name, eventData.date, eventData.time, eventData.location, eventData.description)
        newEvent.map { event =>
          Redirect(routes.SocialCommitteeController.eventList())
        }
      }
    )
  }

  // Define the event form mapping
  val eventForm = Form(
    mapping(
      "name" -> nonEmptyText,
      "date" -> localDate,
      "time" -> localTime,
      "location" -> nonEmptyText,
      "description" -> text
    )(EventForm.apply)(EventForm.unapply)
  )
}
```
In this example, we define the Event model and EventForm case class. We then define the event form and event list routes using the Play Framework's AbstractController. The event form route displays the event submission form, while the event list route displays a list of all events. The submitEventForm route handles the form submission and creates a new event in the database using the EventDAO. Finally, we define the event form mapping using the Play Framework's Form.

