const images = document.querySelectorAll('.images img');
const filterButtons = document.querySelectorAll('.filter button');
// Filter images based on button clicked
filterButtons.forEach(button => {
  button.addEventListener('click', () => {
    const filter = button.dataset.filter;
    images.forEach(image => {
      if (filter === 'all' || image.dataset.filter === filter) {
        image.style.display = 'block';
      } else {
        image.style.display = 'none';
      }
    });
  });
});
// Change image size and layout based on scroll position
window.addEventListener('scroll', () => {
  const scrollTop = window.scrollY;
  images.forEach(image => {
    const imageTop = image.offsetTop;
    const windowHeight = window.innerHeight;
    const imageHeight = image.offsetHeight;
    const imageBottom = imageTop + imageHeight;
    if (imageBottom > scrollTop && imageTop < scrollTop + windowHeight) {
      const distanceFromTop = imageTop - scrollTop;
      const percentageFromTop = distanceFromTop / windowHeight;
      const scale = 1 - percentageFromTop;
      const opacity = 1 - percentageFromTop;
      image.style.transform = `scale(${scale})`;
      image.style.opacity = opacity;
    }
  });
});
```
