func generateIntroduction() -> String {
    let introduction = "In today's society, many people believe that material possessions are the key to happiness. However, this is a fallacy. While material possessions can provide temporary pleasure, they cannot bring true happiness. In this essay, we will explore the reasons why people cannot find true happiness through material possessions."
    return introduction
}
func generateMainPoints() -> String {
    let mainPoints = "Firstly, material possessions are fleeting. They can bring pleasure for a short period of time, but this pleasure is temporary. Secondly, material possessions can actually lead to unhappiness. People often become obsessed with acquiring more and more possessions, which can lead to stress and anxiety. Finally, true happiness comes from within. It comes from having meaningful relationships, pursuing passions, and finding purpose in life."
    return mainPoints
}
func generateConclusion() -> String {
    let conclusion = "In conclusion, material possessions are not the key to happiness. While they can provide temporary pleasure, they cannot bring true happiness. True happiness comes from within, from having meaningful relationships, pursuing passions, and finding purpose in life."
    return conclusion
}
func generateExample() -> String {
    let example = "One example of a person who has found true happiness without material possessions is Mahatma Gandhi. Despite living a simple life with few possessions, Gandhi was able to find true happiness through his pursuit of justice and peace."
    return example
}
func generateEssay() -> String {
    let introduction = generateIntroduction()
    let mainPoints = generateMainPoints()
    let conclusion = generateConclusion()
    let example = generateExample()

    let essay = "\(introduction) \(mainPoints) \(conclusion) \(example)"
    return essay
}
